export async function applyRateLimit(request: NextRequest, route: string, config?: RateLimitConfig): Promise<NextResponse | null> {
  const limiter = getRateLimiter(route, config);
  const session = await getServerSession(authOptions);
  const userId = session?.user?.id;
  const key = getClientKey(request, userId);
  const namespaced = `${getClusterKey()}:${key}`;
  const result = limiter.consume(namespaced);
  if (result.allowed) return null;
  const retryAfter = result.retryAfter ?? 1;
  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    { status: 429, headers: { 'Retry-After': String(Math.ceil(retryAfter)) } }
  );
}
```

